			end

			return spilled.t15.Summon._cache
		end

		spilled.t15.Summon._cacheRead = true

		if not readfile or not isfile then
			return nil
		end

		local ok, result = pcall(function()
			return isfile("barrage_animeadventures_banners.json") and spilled.HttpService:JSONDecode(readfile("barrage_animeadventures_banners.json"))
		end)

		if not ok or type(result) ~= "table" then
