		end

		local cacheUntil = tonumber(result.untilAt)

		spilled.t15.Summon._cacheUntil = cacheUntil

		if cacheUntil and not spilled.t15.Summon.refreshAt then
			spilled.t15.Summon.refreshAt = os.clock() + (cacheUntil - os.time())
		end

		if type(result.units) == "table" then
			if os.time() < (cacheUntil or 0) then
